    pub fn is_exact_bpe(self) -> bool { /* ... */ }

    pub fn label(self) -> &'static str { /* ... */ }
}

fn o200k() -> &'static CoreBPE { /* ... */ }

fn cl100k() -> &'static CoreBPE { /* ... */ }

