@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background-color: var(--bg-canvas);
  color: var(--text-secondary);
  overflow: hidden;
}

/* ─── Layout ─────────────────────────────────────────── */

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: var(--bg-canvas);
  overflow: hidden;
}

.app-container.drag-over {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.app-container.drag-over::after {
  content: 'Drop folder to open';
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--drag-scrim);
  backdrop-filter: blur(6px);
  color: var(--text-primary);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  pointer-events: none;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  height: var(--header-h);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
  gap: 12px;
  flex-shrink: 0;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.action-cluster {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px;
  border-radius: 8px;
  background: var(--hover-overlay);
  border: 1px solid var(--border-muted);
}

.action-cluster .btn-primary {
  box-shadow: none;
}

.preview-inline-actions {
  margin-top: 14px;
}

.token-banner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 8px 12px 0;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--warning-soft);
  border: 1px solid var(--warning-soft-border);
  color: var(--warning);
  font-size: 11.5px;
  line-height: 1.4;
  font-weight: 500;
  flex-shrink: 0;
}

.token-banner.is-hot {
  background: var(--danger-soft);
  border-color: var(--danger-soft-border);
  color: var(--danger);
}

.token-banner svg {
  flex-shrink: 0;
  margin-top: 1px;
}

@media (max-width: 980px) {
  .brand-tag {
    display: none;
  }

  .btn-label {
    /* keep label — primary action must stay readable */
  }

  .header .btn .kbd {
    display: none;
  }

  .path-chip {
    max-width: min(200px, 28vw);
  }
}

@media (max-width: 820px) {
  .brand-text {
    display: none;
  }

  .toolbar {
    flex-wrap: wrap;
    height: auto;
    min-height: var(--toolbar-h);
    padding-top: 6px;
    padding-bottom: 6px;
    row-gap: 6px;
  }

  .search-field {
    width: min(220px, 100%);
    flex: 1 1 160px;
  }
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.brand-mark {
  width: 28px;
  height: 28px;
  border-radius: 7px;
  background: var(--brand-gradient);
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: -0.04em;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
  gap: 2px;
}

.brand-name {
  font-size: 14px;
  font-weight: 650;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.brand-tag {
  font-size: 10px;
  color: var(--text-faint);
  font-weight: 500;
}

.brand-version {
  font-size: 10px;
  color: var(--text-faint);
  font-weight: 500;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* ─── Custom projects panel ─────────────────────────── */

.custom-transfer {
  display: flex;
  align-items: center;
  gap: 14px;
}

.custom-transfer .panel-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
}

.custom-transfer-hint {
  margin-left: auto;
  color: var(--text-faint);
  font-size: 10.5px;
}

.custom-item {
  align-items: stretch;
}

.custom-item-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  gap: 4px;
}

.custom-item-body .history-entry {
  align-self: stretch;
}

.custom-deselect {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 8px 0 34px;
  color: var(--text-faint);
  font-size: 10.5px;
}

.custom-deselect-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--warning);
  font-weight: 550;
}

.custom-note-row {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 0 8px 0 34px;
  color: var(--text-faint);
}

.custom-note-row > svg {
  margin-top: 5px;
  flex-shrink: 0;
}

.custom-note-input {
  flex: 1;
  min-width: 0;
  resize: none;
  padding: 4px 8px;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  background: var(--bg-canvas);
  color: var(--text-secondary);
  font: inherit;
  font-size: 11.5px;
  line-height: 1.45;
}

.custom-note-input::placeholder {
  color: var(--text-faint);
}

.custom-note-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--focus-soft);
}

.path-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: min(420px, 40vw);
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--bg-canvas);
  border: 1px solid var(--border-default);
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 11px;
}

.path-chip span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 16px;
  height: var(--toolbar-h);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
  flex-shrink: 0;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 4px;
}

.toolbar-sep {
  width: 1px;
  height: 18px;
  background: var(--border-default);
  margin: 0 4px;
  flex-shrink: 0;
}

.toolbar-spacer {
  flex: 1;
}

.search-field {
  position: relative;
  width: 220px;
  flex-shrink: 0;
}

.search-field input {
  width: 100%;
  background: var(--bg-canvas);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 6px 28px 6px 30px;
  font-size: 12.5px;
  color: var(--text-secondary);
  transition: border-color 0.12s ease, box-shadow 0.12s ease;
}

.search-field input::placeholder {
  color: var(--text-faint);
}

.search-field input:hover {
  border-color: var(--border-subtle);
}

.search-field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--focus-soft);
}

.search-field .search-icon {
  position: absolute;
  left: 9px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-faint);
  pointer-events: none;
}

.search-field .search-clear {
  position: absolute;
  right: 6px;
  top: 50%;
  transform: translateY(-50%);
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-faint);
  cursor: pointer;
  padding: 0;
}

.search-field .search-clear:hover {
  background: var(--bg-elevated);
  color: var(--text-secondary);
}

.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 16px;
  padding: 0 4px;
  border-radius: 3px;
  border: 1px solid var(--border-default);
  background: var(--bg-elevated);
  color: var(--text-faint);
  font-size: 10px;
  font-family: var(--font-ui);
  font-weight: 500;
  line-height: 1;
}

.main-content {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

.tree-panel {
  width: var(--tree-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-default);
  display: flex;
  flex-direction: column;
  background: var(--bg-surface);
  min-width: 220px;
  max-width: 55vw;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 12px;
  height: 34px;
  border-bottom: 1px solid var(--border-default);
  background: var(--bg-surface);
  flex-shrink: 0;
}

.panel-title {
  font-size: 11px;
  font-weight: 650;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.panel-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--text-faint);
}

.panel-link {
  background: none;
  border: none;
  padding: 0;
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  font-family: inherit;
}

.panel-link:hover {
  color: var(--text-primary);
}

.panel-link:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.resize-handle {
  width: 5px;
  flex-shrink: 0;
  cursor: col-resize;
  background: transparent;
  position: relative;
  z-index: 5;
  transition: background 0.12s ease;
}

.resize-handle::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 2px;
  width: 1px;
  background: transparent;
  transition: background 0.12s ease;
}

.resize-handle:hover,
.resize-handle.active {
  background: var(--accent-soft);
}

.resize-handle:hover::after,
.resize-handle.active::after {
  background: var(--accent);
}

.file-tree {
  flex: 1;
  overflow: auto;
  padding: 6px 6px 12px;
  min-height: 0;
}

.file-tree:focus-visible {
  outline: none;
}

.tree-item {
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 28px;
  padding: 2px 6px 2px 4px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  user-select: none;
  color: var(--text-secondary);
  position: relative;
  font-size: 13px;
  transition: background 0.08s ease;
}

.tree-item:hover {
  background: var(--bg-elevated);
}

.tree-item:focus-visible {
  outline: 1.5px solid var(--focus-ring);
  outline-offset: -1px;
  z-index: 1;
}

.tree-item.is-selected {
  background: var(--selection);
}

.tree-item.is-selected::before,
.tree-item.is-partial::before {
  content: '';
  position: absolute;
  left: 0;
  top: 3px;
  bottom: 3px;
  width: 2.5px;
  border-radius: 1px;
}

.tree-item.is-selected::before {
  background: var(--accent);
}

.tree-item.is-partial {
  background: var(--partial);
}

.tree-item.is-partial::before {
  background: var(--warning);
}

.tree-item.is-filtered-match .tree-name {
  color: var(--text-primary);
}

.tree-chevron {
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border: none;
  background: transparent;
  color: var(--text-faint);
  border-radius: 3px;
  padding: 0;
  cursor: pointer;
}

.tree-chevron:hover {
  color: var(--text-secondary);
  background: var(--chevron-hover);
}

.tree-icon {
  flex-shrink: 0;
  color: var(--text-faint);
  display: grid;
  place-items: center;
}

.tree-item.is-selected .tree-icon,
.tree-item.is-partial .tree-icon {
  color: var(--accent-fg);
}

.tree-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
}

.tree-item:hover .tree-name {
  color: var(--text-primary);
}

.tree-count {
  margin-left: 6px;
  font-size: 10px;
  font-family: var(--font-mono);
  color: var(--text-faint);
  font-variant-numeric: tabular-nums;
}

.tree-size {
  font-size: 10px;
  font-family: var(--font-mono);
  color: var(--text-faint);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
  margin-right: 2px;
}

.tree-tokens {
  font-size: 10px;
  font-family: var(--font-mono);
  color: var(--text-faint);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
  margin-right: 4px;
  white-space: nowrap;
}

.tree-check {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  padding-left: 2px;
  cursor: pointer;
}

.tree-check input {
  width: 14px;
  height: 14px;
  accent-color: var(--accent);
  cursor: pointer;
  margin: 0;
}

.mark {
  background: var(--accent-mark);
  color: var(--text-primary);
  border-radius: 2px;
  padding: 0 1px;
}

.preview-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--bg-canvas);
  min-width: 0;
}

.preview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  height: 36px;
  border-bottom: 1px solid var(--border-default);
  background: var(--bg-surface);
  gap: 8px;
  flex-shrink: 0;
}

.tabs {
  display: flex;
  align-items: stretch;
  gap: 2px;
  height: 100%;
}

.tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 12px;
  height: 100%;
  font-size: 12.5px;
  border: none;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-family: inherit;
  border-radius: 0;
  transition: color 0.1s ease, background 0.1s ease;
}

.tab:hover {
  color: var(--text-secondary);
  background: var(--hover-overlay);
}

.tab.active {
  border-bottom-color: var(--tab-active);
  color: var(--text-primary);
  font-weight: 600;
  background: var(--tab-active-soft);
}

.preview-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.select {
  appearance: none;
  background-color: var(--bg-elevated);
  background-image: var(--select-chevron);
  background-repeat: no-repeat;
  background-position: right 6px center;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 12px;
  height: 26px;
  padding: 0 24px 0 8px;
  cursor: pointer;
  font-family: inherit;
  transition: border-color 0.12s ease;
}

.select:hover {
  border-color: var(--border-subtle);
}

.select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--focus-soft);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
}

.badge-ready {
  background: var(--success-soft);
  color: var(--success);
  border: 1px solid var(--success-soft-border);
}

.badge-loading {
  background: var(--accent-soft);
  color: var(--accent);
  border: 1px solid var(--accent-soft-border);
}

.badge-warn {
  background: var(--warning-soft);
  color: var(--warning);
  border: 1px solid var(--warning-soft-border);
}

.badge-hot {
  background: var(--danger-soft);
  color: var(--danger);
  border: 1px solid var(--danger-soft-border);
}

.preview-content {
  flex: 1;
  margin: 10px 12px 12px;
  padding: 14px 16px;
  overflow: auto;
  font-family: var(--font-mono);
  font-size: 12.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  background: var(--bg-canvas);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  color: var(--text-secondary);
  box-shadow: inset 0 1px 0 var(--inset-highlight);
  min-height: 0;
  position: relative;
}

.preview-content.is-updating::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  background-size: 200% 100%;
  animation: shimmer 1.1s linear infinite;
  opacity: 0.85;
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.output-text {
  margin: 0;
  font: inherit;
  color: inherit;
  white-space: pre-wrap;
  word-break: break-word;
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  height: var(--status-h);
  padding: 0 14px;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-default);
  font-size: 11px;
  color: var(--text-muted);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.status-left {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-faint);
}

.status-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.status-right .sep {
  color: var(--border-default);
}

.status-value {
  color: var(--text-primary);
  font-weight: 650;
}

.status-value.accent {
  color: var(--accent);
}

/* ─── Buttons ────────────────────────────────────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 28px;
  padding: 0 11px;
  font-size: 12.5px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-default);
  background: var(--bg-elevated);
  color: var(--text-secondary);
  cursor: pointer;
  transition: background 0.1s ease, border-color 0.1s ease, color 0.1s ease, box-shadow 0.1s ease;
  font-weight: 500;
  font-family: inherit;
  line-height: 1;
  white-space: nowrap;
}

.btn:hover:not(:disabled) {
  background: var(--bg-overlay);
  border-color: var(--border-subtle);
  color: var(--text-primary);
}

.btn:active:not(:disabled) {
  transform: translateY(0.5px);
}

.btn-primary {
  background: var(--success-bg);
  border-color: var(--success-border);
  color: var(--btn-primary-fg);
  box-shadow: var(--btn-primary-shadow);
  font-weight: 600;
}

.btn-primary:hover:not(:disabled) {
  background: var(--success-bg-hover);
  border-color: var(--success-border-hover);
  color: var(--btn-primary-fg);
}

.btn-ghost {
  background: transparent;
  border-color: transparent;
  font-weight: 500;
  height: 26px;
  padding: 0 8px;
  font-size: 12px;
}

.btn-ghost:hover:not(:disabled) {
  background: var(--bg-elevated);
  border-color: var(--border-default);
}

.btn-ghost.is-active {
  background: var(--accent-soft);
  border-color: var(--accent-soft-border);
  color: var(--accent);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-primary:disabled {
  background: var(--bg-elevated);
  border-color: var(--border-default);
  color: var(--text-muted);
  box-shadow: none;
  opacity: 1;
}

.btn-icon {
  width: 28px;
  padding: 0;
}

.history-toggle {
  gap: 5px;
}

.history-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* ─── Empty / loading states ─────────────────────────── */

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  text-align: center;
  padding: 32px 24px;
  gap: 0;
}

.empty-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  color: var(--text-faint);
  margin-bottom: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
}

.empty-title {
  font-size: 15px;
  font-weight: 650;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.empty-desc {
  font-size: 12.5px;
  color: var(--text-muted);
  max-width: 280px;
  line-height: 1.55;
  margin-bottom: 18px;
}

.empty-hints {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin-top: 14px;
}

.hint-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  color: var(--text-faint);
  font-size: 11px;
}

.loading-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 8px;
  color: var(--text-muted);
}

.loading-center .title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 550;
  color: var(--text-secondary);
}

.loading-center .sub {
  font-size: 11.5px;
  color: var(--text-faint);
}

/* ─── Toasts ─────────────────────────────────────────── */

.toast-viewport {
  position: fixed;
  bottom: 36px;
  right: 16px;
  z-index: 200;
  display: flex;
  flex-direction: column-reverse;
  gap: 8px;
  pointer-events: none;
}

.toast {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 220px;
  max-width: 360px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  box-shadow: var(--shadow-toast);
  color: var(--text-primary);
  font-size: 12.5px;
  font-weight: 500;
  animation: toast-in 0.18s ease-out;
}

.toast.success {
  border-color: var(--toast-success-border);
  background: var(--toast-success-bg);
}

.toast.error {
  border-color: var(--toast-error-border);
  background: var(--toast-error-bg);
}

.toast.info {
  border-color: var(--toast-info-border);
  background: var(--toast-info-bg);
}

.toast-icon {
  flex-shrink: 0;
  display: grid;
  place-items: center;
}

.toast.success .toast-icon {
  color: var(--success);
}

.toast.error .toast-icon {
  color: var(--danger);
}

.toast.info .toast-icon {
  color: var(--accent);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ─── Focus polish ───────────────────────────────────── */

button:focus-visible,
select:focus-visible,
input:focus-visible {
  outline: 1.5px solid var(--focus-ring);
  outline-offset: 1px;
}

/* ─── Scrollbars (subtle) ────────────────────────────── */

.file-tree::-webkit-scrollbar,
.preview-content::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

.file-tree::-webkit-scrollbar-thumb,
.preview-content::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb);
  border-radius: 8px;
  border: 2px solid transparent;
  background-clip: content-box;
}

.file-tree::-webkit-scrollbar-thumb:hover,
.preview-content::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
  background-clip: content-box;
  border: 2px solid transparent;
}

.file-tree::-webkit-scrollbar-track,
.preview-content::-webkit-scrollbar-track {
  background: transparent;
}

/* ─── Utility ────────────────────────────────────────── */

.spin {
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ─── Inline text helpers (no Tailwind dependency) ───── */

.icon-muted {
  color: var(--text-faint);
}

.icon-accent {
  color: var(--accent);
}

.text-strong {
  color: var(--text-primary);
  font-weight: 600;
}

.text-emphasis {
  color: var(--text-primary);
  font-weight: 500;
}

.meta-inline {
  font-size: 11px;
  color: var(--text-faint);
  font-variant-numeric: tabular-nums;
}

.meta-inline strong,
.meta-inline .count {
  color: var(--text-primary);
  font-weight: 650;
}

.meta-filter {
  margin-left: 8px;
  color: var(--accent);
}

.status-folder {
  color: var(--text-muted);
}

.status-dot {
  color: var(--border-subtle);
}

.status-busy {
  color: var(--warning);
  font-weight: 550;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.status-format {
  color: var(--text-faint);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10px;
}

.status-value.warn {
  color: var(--warning);
}

.status-value.danger {
  color: var(--danger);
}

.token-hot {
  color: var(--danger) !important;
}

.token-warm {
  color: var(--warning) !important;
}

/* ─── Help dialog ────────────────────────────────────── */

.help-overlay {
  position: fixed;
  inset: 0;
  z-index: 150;
  display: grid;
  place-items: center;
  background: var(--scrim);
  backdrop-filter: blur(4px);
  padding: 24px;
  animation: toast-in 0.16s ease-out;
}

.help-card {
  width: min(420px, 100%);
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: 12px;
  box-shadow: var(--shadow-dialog);
  padding: 16px 18px 14px;
}

.help-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.help-header h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.help-list {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.help-list > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 0;
  border-bottom: 1px solid var(--border-muted);
}

.help-list > div:last-child {
  border-bottom: none;
}

.help-list dt {
  margin: 0;
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}

.help-list dd {
  margin: 0;
  color: var(--text-muted);
  font-size: 12.5px;
  text-align: right;
}

.help-foot {
  margin: 12px 0 0;
  padding-top: 10px;
  border-top: 1px solid var(--border-default);
  font-size: 11.5px;
  color: var(--text-faint);
  line-height: 1.45;
}

.help-theme {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-default);
}

.help-theme-label {
  font-size: 11px;
  font-weight: 650;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* ─── Folder history dialog ─────────────────────────── */

.history-overlay {
  position: fixed;
  inset: 0;
  z-index: 160;
  display: grid;
  place-items: start center;
  padding: 74px 24px 24px;
  background: var(--scrim);
  backdrop-filter: blur(4px);
  animation: toast-in 0.16s ease-out;
}

.history-card {
  width: min(680px, 100%);
  max-height: min(680px, calc(100vh - 98px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: 12px;
  box-shadow: var(--shadow-dialog);
}

.history-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px 12px;
  border-bottom: 1px solid var(--border-default);
}

.history-header h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.02em;
}

.history-header p {
  margin: 4px 0 0;
  color: var(--text-faint);
  font-size: 11.5px;
}

.history-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 18px;
  color: var(--text-faint);
  font-size: 11px;
  border-bottom: 1px solid var(--border-muted);
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: auto;
  padding: 8px;
}

.history-item {
  display: flex;
  align-items: stretch;
  gap: 6px;
  min-width: 0;
  padding: 3px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
}

.history-item:hover,
.history-item.is-current {
  background: var(--bg-elevated);
  border-color: var(--border-default);
}

.history-entry {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
  padding: 7px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  text-align: left;
  font: inherit;
  cursor: pointer;
}

.history-entry:hover:not(:disabled) {
  background: var(--hover-overlay);
}

.history-entry:disabled {
  opacity: 0.55;
  cursor: wait;
}

.history-entry-icon {
  flex-shrink: 0;
  color: var(--accent);
}

.history-entry-copy {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.history-entry-copy strong {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 12.5px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.history-entry-copy span,
.history-entry-copy small {
  overflow: hidden;
  color: var(--text-faint);
  font-family: var(--font-mono);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.history-entry-copy small {
  font-family: var(--font-ui);
  font-size: 10px;
}

.history-current {
  flex-shrink: 0;
  padding: 2px 6px;
  border-radius: 999px;
  background: var(--success-soft);
  color: var(--success);
  font-size: 10px;
  font-weight: 600;
}

.history-item-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.history-action {
  color: var(--text-faint);
}

.history-action.is-pinned {
  color: var(--accent);
}

.history-action.danger:hover:not(:disabled) {
  color: var(--danger);
  border-color: var(--danger-soft-border);
  background: var(--danger-soft);
}

.history-empty {
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 8px;
  padding: 42px 24px 48px;
  color: var(--text-faint);
  text-align: center;
}

.history-empty svg {
  color: var(--accent);
  margin-bottom: 2px;
}

.history-empty strong {
  color: var(--text-primary);
  font-size: 13px;
}

.history-empty span {
  max-width: 300px;
  font-size: 11.5px;
  line-height: 1.45;
}

/* GitHub-style appearance segmented control */
.theme-segment {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 4px;
  padding: 3px;
  background: var(--bg-canvas);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
}

.theme-segment-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 30px;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.1s ease, color 0.1s ease, border-color 0.1s ease, box-shadow 0.1s ease;
}

.theme-segment-btn:hover {
  color: var(--text-primary);
  background: var(--hover-overlay);
}

.theme-segment-btn.is-active {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border-color: var(--border-default);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
  font-weight: 600;
}

[data-theme='dark'] .theme-segment-btn.is-active {
  background: var(--bg-elevated);
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.2);
}

.theme-toggle {
  color: var(--text-muted);
}

.theme-toggle:hover:not(:disabled) {
  color: var(--text-primary);
}

/* ─── File tree: preview highlight ───────────────────── */

.tree-item.is-previewing {
  background: var(--accent-soft);
  box-shadow: inset 0 0 0 1px var(--accent-soft-border);
}

.tree-item.is-previewing .tree-name {
  color: var(--text-primary);
  font-weight: 550;
}

.tab-file-name {
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
  opacity: 0.85;
  font-size: 11px;
}

/* ─── File viewer ────────────────────────────────────── */

.preview-content.is-file-view {
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
}

.file-viewer {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.file-viewer-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-default);
  background: var(--bg-surface);
  flex-shrink: 0;
  flex-wrap: wrap;
}

.file-viewer-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1;
  color: var(--text-muted);
  font-size: 12px;
}

.file-viewer-path {
  font-family: var(--font-mono);
  color: var(--text-primary);
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-viewer-chip {
  flex-shrink: 0;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  color: var(--text-faint);
  font-size: 10px;
  font-family: var(--font-mono);
}

.file-viewer-chip.warn {
  color: var(--warning);
  border-color: var(--warning-soft-border);
  background: var(--warning-soft);
}

.file-viewer-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.file-viewer-code {
  flex: 1;
  margin: 0;
  padding: 14px 16px;
  overflow: auto;
  font-family: var(--font-mono);
  font-size: 12.5px;
  line-height: 1.55;
  white-space: pre;
  tab-size: 2;
  background: var(--bg-canvas);
  color: var(--text-secondary);
  border: none;
  border-radius: 0;
  min-height: 0;
}

.file-viewer-code code {
  font: inherit;
  background: transparent;
  color: inherit;
}

/* highlight.js token colors — theme-aware */
.hljs {
  background: transparent;
  color: var(--text-secondary);
}

.hljs-comment,
.hljs-quote {
  color: var(--text-faint);
  font-style: italic;
}

.hljs-keyword,
.hljs-selector-tag,
.hljs-literal,
.hljs-section,
.hljs-link {
  color: #ff7b72;
}

[data-theme='light'] .hljs-keyword,
[data-theme='light'] .hljs-selector-tag,
[data-theme='light'] .hljs-literal {
  color: #cf222e;
}

.hljs-string,
.hljs-title,
.hljs-name,
.hljs-type,
.hljs-attribute,
.hljs-symbol,
.hljs-bullet,
.hljs-addition,
.hljs-variable,
.hljs-template-tag,
.hljs-template-variable {
  color: #a5d6ff;
}

[data-theme='light'] .hljs-string,
[data-theme='light'] .hljs-title,
[data-theme='light'] .hljs-name,
[data-theme='light'] .hljs-attribute {
  color: #0a3069;
}

.hljs-number,
.hljs-built_in,
.hljs-builtin-name,
.hljs-params {
  color: #79c0ff;
}

[data-theme='light'] .hljs-number,
[data-theme='light'] .hljs-built_in {
  color: #0550ae;
}

.hljs-tag,
.hljs-meta {
  color: #7ee787;
}

[data-theme='light'] .hljs-tag,
[data-theme='light'] .hljs-meta {
  color: #116329;
}

.hljs-attr {
  color: #79c0ff;
}

[data-theme='light'] .hljs-attr {
  color: #0550ae;
}

.hljs-deletion {
  color: var(--danger);
}

.hljs-emphasis {
  font-style: italic;
}

.hljs-strong {
  font-weight: 700;
}

/* Open with dropdown */
.open-with-menu {
  position: relative;
}

.open-with-details {
  position: relative;
}

.open-with-details > summary {
  list-style: none;
  cursor: pointer;
}

.open-with-details > summary::-webkit-details-marker {
  display: none;
}

.open-with-dropdown {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  z-index: 50;
  min-width: 180px;
  padding: 4px;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  box-shadow: var(--shadow-dialog);
}

.open-with-item {
  display: block;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 12.5px;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.open-with-item:hover {
  background: var(--hover-overlay);
  color: var(--text-primary);
}

/* Context menu */
.ctx-menu {
  position: fixed;
  z-index: 300;
  min-width: 200px;
  padding: 4px;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  box-shadow: var(--shadow-dialog);
}

.ctx-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 12.5px;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.ctx-item:hover {
  background: var(--hover-overlay);
  color: var(--text-primary);
}

.ctx-sep {
  height: 1px;
  margin: 4px 6px;
  background: var(--border-default);
}

/* Browser mode notice */
.browser-mode-banner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 14px;
  background: var(--accent-soft);
  border-bottom: 1px solid var(--accent-soft-border);
  color: var(--accent);
  font-size: 11.5px;
  line-height: 1.4;
  flex-shrink: 0;
}

.browser-mode-banner code {
  font-family: var(--font-mono);
  font-size: 11px;
  padding: 0 4px;
  border-radius: 3px;
  background: var(--bg-canvas);
  color: var(--text-primary);
}

.browser-mode-banner strong {
  color: var(--text-primary);
  font-weight: 650;
}

.browser-mode-banner svg {
  flex-shrink: 0;
  margin-top: 1px;
}

/* ─── Phase 0-4 Upgrades: Budget Bar, Skeleton Pills, Git Badges & Prompt Studio ─── */

.tree-virtual-container {
  position: relative;
  width: 100%;
}

.tree-git-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: 3px;
  font-size: 9.5px;
  font-weight: 700;
  font-family: var(--font-mono);
  flex-shrink: 0;
  line-height: 1;
}

.tree-git-badge.git-M {
  background: var(--warning-soft);
  color: var(--warning);
  border: 1px solid var(--warning-soft-border);
}

.tree-git-badge.git-A,
.tree-git-badge.git-U {
  background: var(--success-soft);
  color: var(--success);
  border: 1px solid var(--success-soft-border);
}

.tree-git-badge.git-D {
  background: var(--danger-soft);
  color: var(--danger);
  border: 1px solid var(--danger-soft-border);
}

.tree-skel-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 16px;
  min-width: 18px;
  padding: 0 3px;
  border-radius: 3px;
  border: 1px solid var(--border-default);
  background: transparent;
  color: var(--text-faint);
  font-size: 9.5px;
  font-weight: 700;
  font-family: var(--font-mono);
  cursor: pointer;
  flex-shrink: 0;
  opacity: 0;
  transition: opacity 0.1s ease, background 0.1s ease, color 0.1s ease;
}

.tree-item:hover .tree-skel-btn,
.tree-skel-btn.is-active {
  opacity: 1;
}

.tree-skel-btn.is-active {
  background: var(--accent-soft);
  border-color: var(--accent-soft-border);
  color: var(--accent);
}

.tree-skel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.budget-bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 16px;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
  font-size: 11.5px;
  flex-shrink: 0;
  flex-wrap: wrap;
}

.budget-meter-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 180px;
}

.budget-track {
  width: 110px;
  height: 7px;
  border-radius: 999px;
  background: var(--bg-overlay);
  overflow: hidden;
  border: 1px solid var(--border-default);
}

.budget-fill {
  height: 100%;
  background: var(--success);
  transition: width 0.18s ease, background 0.18s ease;
}

.budget-fill.is-warn {
  background: var(--warning);
}

.budget-fill.is-over {
  background: var(--danger);
}

.budget-label {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.redact-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--success-soft);
  border: 1px solid var(--success-soft-border);
  color: var(--success);
  font-size: 10.5px;
  font-weight: 600;
}

.disk-changed-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--warning-soft);
  border: 1px solid var(--warning-soft-border);
  color: var(--warning);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}

.top-consumers-drawer {
  margin: 8px 12px 0;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  font-size: 11.5px;
  flex-shrink: 0;
}

.top-consumers-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
  font-weight: 650;
  color: var(--text-primary);
}

.top-consumers-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 170px;
  overflow: auto;
}

.top-consumer-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-canvas);
  border: 1px solid var(--border-muted);
}

.top-consumer-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
}

.top-consumer-tokens {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.prompt-studio-bar {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 12px;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
  flex-shrink: 0;
}

.prompt-studio-controls {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.prompt-studio-textarea {
  width: 100%;
  min-height: 54px;
  max-height: 130px;
  resize: vertical;
  padding: 6px 8px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-default);
  background: var(--bg-canvas);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.45;
}

.prompt-studio-textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--focus-soft);
}


/**
 * Platform detection and shortcut formatting.
 *
 * Single source of truth for "Cmd on macOS, Ctrl elsewhere" so labels in
 * JSX/tooltips can never drift from the keydown handler. Detection prefers
 * `navigator.userAgentData.platform` (Chromium/WebView2), then `userAgent`,
 * then the deprecated `navigator.platform` as a last resort.
 */

